   127→        public void Commit(bool skipRoot = false, WriteFlags writeFlags = WriteFlags.None)
   128→        {
   129→            if (!_allowCommits)
   130→            {
   131→                ThrowReadOnlyTrieException();
   132→            }
   133→
   134→            int maxLevelForConcurrentCommit = _writeBeforeCommit switch
   135→            {
   136→                > 4 * 16 * 16 => 2, // we separate at three top levels
   137→                > 4 * 16 => 1, // we separate at two top levels
   138→                > 4 => 0, // we separate at top level
   139→                _ => -1
   140→            };
   141→
   142→            _writeBeforeCommit = 0;
   143→
   144→            using ICommitter committer = TrieStore.BeginCommit(RootRef, writeFlags);
   145→            if (RootRef is not null && RootRef.IsDirty)
   146→            {
   147→                TreePath path = TreePath.Empty;
   148→                RootRef = Commit(committer, ref path, RootRef, skipSelf: skipRoot, maxLevelForConcurrentCommit: maxLevelForConcurrentCommit);
   149→            }
   150→
   151→            // Sometimes RootRef is set to null, so we still need to reset roothash to empty tree hash.
   152→            SetRootHash(RootRef?.Keccak, true);
   153→        }
