   155→        private TrieNode Commit(ICommitter committer, ref TreePath path, TrieNode node, int maxLevelForConcurrentCommit, bool skipSelf = false)
   156→        {
   157→            if (!_allowCommits)
   158→            {
   159→                ThrowReadOnlyTrieException();
   160→            }
   161→
   162→            if (node!.IsBranch)
   163→            {
   164→                if (path.Length > maxLevelForConcurrentCommit)
   165→                {
   166→                    for (int i = 0; i < 16; i++)
   167→                    {
   168→                        if (node.IsChildDirty(i))
   169→                        {
   170→                            path.AppendMut(i);
   171→                            TrieNode childNode = node.GetChildWithChildPath(TrieStore, ref path, i);
   172→                            TrieNode newChildNode = Commit(committer, ref path, childNode, maxLevelForConcurrentCommit);
   173→                            if (!ReferenceEquals(childNode, newChildNode))
   174→                            {
   175→                                node[i] = newChildNode;
   176→                            }
   177→                            path.TruncateOne();
   178→                        }
   179→                        else
   180→                        {
   181→                            if (_logger.IsTrace)
   182→                            {
   183→                                Trace(node, ref path, i);
   184→                            }
   185→                        }
   186→                    }
   187→                }
   188→                else
   189→                {
   190→                    Task CreateTaskForPath(TreePath childPath, TrieNode childNode, int idx) => Task.Run(() =>
   191→                    {
   192→                        TrieNode newChild = Commit(committer, ref childPath, childNode!, maxLevelForConcurrentCommit);
   193→                        if (!ReferenceEquals(childNode, newChild))
   194→                        {
   195→                            node[idx] = newChild;
   196→                        }
   197→                        committer.ReturnConcurrencyQuota();
   198→                    });
   199→
   200→                    ArrayPoolList<Task>? childTasks = null;
   201→
   202→                    for (int i = 0; i < 16; i++)
   203→                    {
   204→                        if (node.IsChildDirty(i))
   205→                        {
   206→                            if (i < 15 && committer.TryRequestConcurrentQuota())
   207→                            {
   208→                                childTasks ??= new ArrayPoolList<Task>(15);
   209→                                TreePath childPath = path.Append(i);
   210→                                TrieNode childNode = node.GetChildWithChildPath(TrieStore, ref childPath, i);
   211→                                childTasks.Add(CreateTaskForPath(childPath, childNode, i));
   212→                            }
   213→                            else
   214→                            {
   215→                                path.AppendMut(i);
   216→                                TrieNode childNode = node.GetChildWithChildPath(TrieStore, ref path, i);
   217→                                TrieNode newChildNode = Commit(committer, ref path, childNode!, maxLevelForConcurrentCommit);
   218→                                if (!ReferenceEquals(childNode, newChildNode))
   219→                                {
   220→                                    node[i] = newChildNode;
   221→                                }
   222→                                path.TruncateOne();
   223→                            }
   224→                        }
   225→                        else
   226→                        {
   227→                            if (_logger.IsTrace)
   228→                            {
   229→                                Trace(node, ref path, i);
   230→                            }
   231→                        }
   232→                    }
   233→
   234→                    if (childTasks is not null)
   235→                    {
   236→                        Task.WaitAll(childTasks.AsSpan());
   237→                        childTasks.Dispose();
   238→                    }
   239→                }
   240→            }
   241→            else if (node.NodeType == NodeType.Extension)
   242→            {
   243→                int previousPathLength = node.AppendChildPath(ref path, 0);
   244→                TrieNode extensionChild = node.GetChildWithChildPath(TrieStore, ref path, 0);
   245→                if (extensionChild is null)
   246→                {
   247→                    ThrowInvalidExtension();
   248→                }
   249→
   250→                if (extensionChild.IsDirty)
   251→                {
   252→                    TrieNode newExtensionChild = Commit(committer, ref path, extensionChild, maxLevelForConcurrentCommit);
   253→                    if (!ReferenceEquals(newExtensionChild, extensionChild))
   254→                    {
   255→                        node[0] = newExtensionChild;
   256→                    }
   257→                }
   258→                else
   259→                {
   260→                    if (_logger.IsTrace) TraceExtensionSkip(extensionChild);
   261→                }
   262→                path.TruncateMut(previousPathLength);
   263→            }
   264→
   265→            node.ResolveKey(TrieStore, ref path, bufferPool: _bufferPool);
   266→            node.Seal();
   267→
   268→            if (node.FullRlp.Length >= 32)
   269→            {
   270→                if (!skipSelf)
   271→                {
   272→                    node = committer.CommitNode(ref path, node);
   273→                }
   274→            }
   275→            else
   276→            {
   277→                if (_logger.IsTrace) TraceSkipInlineNode(node);
   278→            }
   279→
   280→            return node;
